        public Report SelDirectMixParlay(DateTime reportDate, int betType)
        {
            var allTotalSummary = Fanex.Tarus.Reports.Resource.NormalMixParlayReport.AllTotal;

            var result = new Report
            {
                ReportDetails = new List<ReportDetail>(),
                Total = new ReportTotal
                {
                    NormalTotal = new ReportDetail
                    {
                        Name = allTotalSummary
                    },
                    EightRMTotal = new ReportDetail(),
                    BARMTotal = new ReportDetail(),
                    AllTotal = new ReportDetail(),
                    GrandTotal = new ReportGrandTotal()
                }
            };
            try
            {
                #region Declaration

                DataTable dataTable = _mixParlayReportAccess.SelDirectMixParlay(reportDate, betType);

                int currentSporttype = 0;
                int sportIndex = 0;
                ReportDetail sportTotal = new ReportDetail
                {
                    RowType = new DisplayRowType
                    {
                        Id = RowType.SportTotal
                    }
                };

                var emptyRow = new ReportDetail
                {
                    RowType = new DisplayRowType
                    {
                        Id = RowType.EmptyRow
                    }
                };

                #endregion Declaration

                if (dataTable != null && dataTable.Rows.Count > 0)
                {
                    #region ForEach

                    var reportDetailX = new ReportDetail();
                    var rows = dataTable.Select(null, "SportType ASC, Bettype ASC");
                    if (rows.Length > 0)
                    {
                        currentSporttype = CastAide.AsInt32(rows[0]["SportType"]);
                    }

                    foreach (DataRow row in rows)
                    {
                        reportDetailX = new ReportDetail
                        {
                            Status = CastAide.AsString(row["Status"]),
                            WinLoss = CastAide.AsDecimal(row["WinLost"]),
                            Position = CastAide.AsDecimal(row["Position"]),
                            Commission = CastAide.AsDecimal(row["Commission"]),
                            LineTotal = CastAide.AsDecimal(row["LineTotal"]),
                            Turnover = CastAide.AsDecimal(row["Turnover"]),

                            SportType = new Sporttype
                            {
                                Id = CastAide.AsInt32(row["SportType"])
                            },

                            BetType = new Fanex.Tarus.Reports.Entities.Sport.BaseModel
                            {
                                Id = CastAide.AsInt32(row["BetType"])
                            },

                            RowType = new DisplayRowType
                            {
                                Id = RowType.Normal
                            }
                        };

                        reportDetailX.Name = RefData.GetBetTypeName(reportDetailX.BetType.Id.ToString(), "EN") + "(" + reportDetailX.Status + ")";
                        reportDetailX.Margin = CalculateMargin(reportDetailX);
                        #region CalculateReportTotal

                        result.Total.NormalTotal.WinLoss += reportDetailX.WinLoss;
                        result.Total.NormalTotal.Position += reportDetailX.Position;
                        result.Total.NormalTotal.Commission += reportDetailX.Commission;
                        result.Total.NormalTotal.LineTotal += reportDetailX.LineTotal;
                        result.Total.NormalTotal.Turnover += reportDetailX.Turnover;

                        #endregion CalculateReportTotal
                        #region SportTypeChangeProccess

                        if (reportDetailX.SportType.Id != currentSporttype)
                        {
                            sportIndex++;
                            sportTotal.Id = currentSporttype;
                            sportTotal.Name = GetSportTotalName(currentSporttype);
                            sportTotal.Margin = CalculateMargin(sportTotal);
                            result.ReportDetails.Add(sportTotal);
                            result.ReportDetails.Add(emptyRow);

                            #region InitSportTotal

                            sportTotal = new ReportDetail
                            {
                                RowType = new DisplayRowType
                                {
                                    Id = RowType.SportTotal
                                }
                            };

                            sportTotal.WinLoss = reportDetailX.WinLoss;
                            sportTotal.Position = reportDetailX.Position;
                            sportTotal.Commission = reportDetailX.Commission;
                            sportTotal.LineTotal = reportDetailX.LineTotal;
                            sportTotal.Turnover = reportDetailX.Turnover;

                            #endregion InitSportTotal

                            currentSporttype = reportDetailX.SportType.Id;

                        }
                        else
                        {
                            #region CalculateSportTotal

                            sportTotal.WinLoss += reportDetailX.WinLoss;
                            sportTotal.Position += reportDetailX.Position;
                            sportTotal.Commission += reportDetailX.Commission;
                            sportTotal.LineTotal += reportDetailX.LineTotal;
                            sportTotal.Turnover += reportDetailX.Turnover;

                            #endregion CalculateSportTotal
                        }

                        reportDetailX.RowIndex = sportIndex;
                        result.ReportDetails.Add(reportDetailX);

                        #endregion SportTypeChangeProccess

                    }

                    #endregion ForEach
                    #region TotalOfLastSport

                    sportIndex++;
                    sportTotal.Name = GetSportTotalName(currentSporttype);
                    sportTotal.Margin = CalculateMargin(sportTotal);
                    result.ReportDetails.Add(sportTotal);
                    result.ReportDetails.Add(emptyRow);
                    currentSporttype = reportDetailX.SportType.Id;

                    #endregion TotalOfLastSport

                    result.Total.NormalTotal.Margin = CalculateMargin(result.Total.NormalTotal);
                }
                SessionExtension.AddSession(HttpContext.Current.Session, _normalMixParlayReport, result);
            }
            catch (Exception ex)
            {
                LogExtensions.ExceptionHandler(ex);
            }
            return result;
        }

        public void ExportToExcel_DirectMixParlay(DateTime reportDate, int betType)
        {
            var excelFile = new ExcelFile();
            var sheetName = Fanex.Tarus.Reports.Resource.NormalMixParlayReport.SheetName;
            var reportName = string.Format(Fanex.Tarus.Reports.Resource.NormalMixParlayReport.ReportName, reportDate);
            var wsReport = excelFile.Worksheets.Add(sheetName);

            int currentRow = 0;
            const int startCol = 0;
            var report = (Report)SessionExtension.GetSession(HttpContext.Current.Session, _normalMixParlayReport);
            if (report == null)
            {
                report = SelDirectMixParlay(reportDate, betType);
            }
            ExportLiveOrNoneLive(ref wsReport, startCol, ref currentRow, report, reportDate, betType);
            (new ReportHelpers()).ReponseExcelFile(excelFile, reportName);
        }

