        private void ExportEmptyRow(ref ExcelWorksheet wsReport,
           int startCol, ref int currentRow, CellStyle cellStyle)
        {
            var endCol = startCol + 6;
            wsReport.Cells.GetSubrangeAbsolute(currentRow, startCol, currentRow, endCol).Style = cellStyle;
            wsReport.Cells.GetSubrangeAbsolute(currentRow, startCol, currentRow, endCol).Merged = true;
            wsReport.Cells.GetSubrangeAbsolute(currentRow, startCol, currentRow, endCol).Value = "";
            wsReport.Cells.GetSubrangeAbsolute(currentRow, startCol, currentRow, endCol).Style.HorizontalAlignment = HorizontalAlignmentStyle.Center;
            currentRow++;
        }

        private string GetSportTotalName(int sporttype)
        {
            var sportTotalName = "";
            switch (sporttype)
            {
                case Sports.Soccer:
                    sportTotalName = Fanex.Tarus.Reports.Resource.NormalMixParlayReport.SoccerSportTotal;
                    break;
                case Sports.CombinationMixParlay:
                    sportTotalName = Fanex.Tarus.Reports.Resource.NormalMixParlayReport.MultiSportTotal;
                    break;
                default:
                    sportTotalName = Fanex.Tarus.Reports.Resource.NormalMixParlayReport.OthersSportTotal;
                    break;
            }
            return sportTotalName;
        }
